// Bundled parking-lot photos, keyed by lot id (see src/data/parking.ts). Files
// live in public/assets/parking/{id}.webp, generated by
// scripts/optimize-parking-photos.js. A lot with no entry falls back to the
// striped placeholder on its page.
const LOTS_WITH_PHOTOS = new Set([
  'g1', 'g2', 'g3', 'g4', 'g5', 'g6', 'g7', 'g8', 'g9', 'g11',
  'g12', 'g12-e', 'g13', 'g14', 'pv-north', 'pv-south', 'pyramid',
  'e1', 'e2', 'e3', 'e4', 'e5', 'e6', 'e7', 'e8', 'e9', 'e10', 'e11',
]);

export function parkingImage(lotId: string): string | null {
  return LOTS_WITH_PHOTOS.has(lotId) ? `/assets/parking/${lotId}.webp` : null;
}
